// Writes supabase/tests/database/status_vectors.test.sql from vectors/status.json,
// so the SQL status rules are tested against the same cases as the TS ones. CI
// fails if the committed file is stale.
import { readFileSync, writeFileSync } from "node:fs";

const { vectors } = JSON.parse(
  readFileSync(new URL("../vectors/status.json", import.meta.url), "utf8"),
) as { vectors: { name: string; input: Record<string, unknown>; expected: string }[] };

const quote = (s: string) => `'${s.replaceAll("'", "''")}'`;
const lines = [
  "-- Generated by `pnpm core:gen` from packages/core/vectors/status.json. Do not edit.",
  "begin;",
  "create extension if not exists pgtap with schema extensions;",
  `select plan(${vectors.length});`,
  ...vectors.map(
    (v) =>
      `select is(internal.compute_status(${quote(JSON.stringify(v.input))}::jsonb)::text, ${quote(v.expected)}, ${quote(v.name)});`,
  ),
  "select * from finish();",
  "rollback;",
  "",
];
const out = new URL("../../../supabase/tests/database/status_vectors.test.sql", import.meta.url);
writeFileSync(out, lines.join("\n"));
console.log(`wrote ${out.pathname}`);
